        "context": "這間老屋不參賽，圖上卻有長者每天會走的路。你問坡道怎麼轉，傾城蹲下來量，很有耐心。助理來電說住戶也有意見，她卻叫人等回辦公室。你看見同一個下午的兩種待遇，她也注意到了，先問你是不是有話想說，捲尺還留在她手裡，她等你把話說完。",
        "line": "「你的問題有意思。我不是每份意見都看得下去……你剛才是不是想問，那其他人的呢？」",
