    "stalledLine": "「昨天能自己談，今天還是會問很多次。我想今天先做草莓，你的藍莓下次另外做。你願意試吃嗎？」「不過，之前工作的事還沒談好。今天能坐下來聊，不代表那些問題都解決了。」",
